import { readFile } from 'node:fs/promises';

let recordsPromise;
function loadRecords() {
  if (!recordsPromise) {
    recordsPromise = readFile(new URL('./records.json', import.meta.url), 'utf8').then(JSON.parse);
  }
  return recordsPromise;
}

export async function listTools() {
  return [
    {
      name: 'search_records',
      description: 'Search records by case-insensitive name match',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Substring to match against record names (case-insensitive)' },
          limit: { type: 'integer', minimum: 1, maximum: 4, default: 2, description: 'Maximum number of records to return' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'search_records') {
    const err = new Error('Unknown tool: ' + name);
    err.code = -32601;
    throw err;
  }

  // Validate arguments
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    const err = new Error('Invalid arguments');
    err.code = -32602;
    throw err;
  }

  const { query, limit = 2, ...rest } = args;

  if (Object.keys(rest).length > 0) {
    const err = new Error('Unexpected arguments: ' + Object.keys(rest).join(', '));
    err.code = -32602;
    throw err;
  }

  if (typeof query !== 'string') {
    const err = new Error('query must be a string');
    err.code = -32602;
    throw err;
  }

  if (!Number.isInteger(limit) || limit < 1 || limit > 4) {
    const err = new Error('limit must be an integer between 1 and 4');
    err.code = -32602;
    throw err;
  }

  const records = await loadRecords();
  const q = query.toLowerCase();
  const matching = records.filter(r => typeof r.name === 'string' && r.name.toLowerCase().includes(q));
  const result = matching.slice(0, limit);

  return {
    content: [{ type: 'text', text: JSON.stringify({ records: result }) }]
  };
}
